 for name,module in list(sys.modules.items()):
  if name=='friday_commands' or name.startswith('friday_commands.') or name=='friday_chat' or name.startswith('friday_chat.'):
   p=Path(module.__file__).resolve();owner='friday-commands' if name.startswith('friday_commands') else 'friday-chat';root=case/'packages'/owner/'src'
